/* ===== rv1：🟡 待審 批次審核（只限擁有者）=====
   全選（預設全勾）＋逐筆勾選；✅ 核准已勾選／❌ 退回已勾選，逐筆呼叫原本的 floor/review（和單筆審核同一條路）。點一列展開全文。關閉：localStorage.reviewBulkOff='1' */
(function(){try{if(localStorage.getItem('reviewBulkOff')==='1')return}catch(_){return}
 var SR0=showReviews;
 function typ(t){var nv=t.plan&&!Array.isArray(t.plan)&&t.plan.novel;if(t.kind==='spawn')return'🧬 分身申請';if(nv&&nv.stage==='outline')return'📖 小說大綱';if(nv&&nv.stage==='chapter')return'📖 小說章節';if(/衛教/.test(t.order_text||''))return'🩺 衛教文章';if(/學習|learn/i.test(t.order_text||''))return'📚 學習';return'🛠️ 作品'}
 function use(t){var k=typ(t);return k==='📖 小說大綱'?'核准後在「因序小說」書架上架並開始連載':k==='📖 小說章節'?'核准後成為因序小說正式章節':k==='🧬 分身申請'?'核准後會新增一位子代理（建立新 AI）':/衛教/.test(t.order_text||'')?'衛教文章：可放進電子書／暗星教學內容':/主題曲|歌詞/.test(t.order_text||'')?'因序小說主題曲歌詞（可交給音樂工坊）':/資安/.test(t.order_text||'')?'資安檢查報告：給擁有者修補系統用':/改編|劇本|分鏡/.test(t.order_text||'')?'影片改編腳本：AI 短視頻企劃中心':'協作池作品：核准後列入已核准成果'}
 function gk(s){return String(s||'').replace(/[0-9０-９#＃]+/g,'').replace(/[\s，,。：:、（）()《》「」\-—·・]/g,'').slice(0,22)}
 function one(s,n){s=String(s||'').replace(/\s+/g,' ').trim();return s.length>n?s.slice(0,n)+'…':s}
 showReviews=async function(){if(!OWNER)return SR0();
  open('<h3>🟡 審核佇列</h3><p class="muted">載入中…</p>');var d;try{d=await api('floor','reviews',{limit:300})}catch(e){sh.innerHTML+='<p class="muted">'+esc(e.message)+'</p>';return}
  var L0=d.tasks||[],G={};L0.forEach(function(t){var nv=t.plan&&!Array.isArray(t.plan)&&t.plan.novel;if(t.kind!=='work'||nv||(t.plan&&t.plan.ai_review))return;var k=gk(t.order_text);G[k]=(G[k]||0)+1});var hid=0,L=L0.filter(function(t){var nv=t.plan&&!Array.isArray(t.plan)&&t.plan.novel;if(t.kind==='work'&&!nv&&!(t.plan&&t.plan.ai_review)&&G[gk(t.order_text)]>=2){hid++;return false}return true}),cnt={};L.forEach(function(t){var k=typ(t);cnt[k]=(cnt[k]||0)+1});
  open('<h3>🟡 作品審核（'+L.length+'）</h3><p class="muted">只列完成的作品。'+(hid?hid+' 份同題練習稿交給學階最高的 AI 初審中（每 10 分鐘處理一批，最佳版本會升上來）。':'')+' <a href="#" id="rvAI" style="color:#a5b4fc">🤖 AI 初審紀錄</a></p><p class="muted">'+Object.keys(cnt).map(function(k){return esc(k)+' '+cnt[k]}).join('　')+'</p>'+
   '<p style="position:sticky;top:0;background:#0b1018;padding:6px 0;z-index:2"><label style="font-size:15px"><input type="checkbox" id="rvAll" checked> 全選</label> <span class="muted" id="rvN"></span><br><button class="btn ok" id="rvOk">✅ 核准已勾選</button> <button class="btn" id="rvNo" style="background:#7f1d1d">❌ 退回已勾選</button> <span class="muted" id="rvE"></span></p>'+
   '<div id="rvL">'+(L.map(function(t,i){return'<div class="card" data-i="'+i+'" style="margin:6px 0"><label style="display:flex;gap:8px;align-items:flex-start"><input type="checkbox" class="rvC" data-id="'+esc(t.id)+'" checked style="margin-top:4px"><span style="flex:1"><b>'+esc(typ(t))+'</b> · '+esc(t.agent_name||t.agent_id)+' <span class="muted">'+esc(t.zone_label||t.zone||'')+' · '+esc(tp(t.updated_at))+'</span><br>'+esc(one(t.order_text,60))+'<div style="font-size:12px;color:#86efac">用途：'+esc(use(t))+'</div>'+(t.plan&&t.plan.ai_review?'<div style="font-size:12px;color:#fcd34d">🤖 AI 初審：'+esc(t.plan.ai_review.reviewer)+'（'+esc(t.plan.ai_review.rank)+'）從 '+(+t.plan.ai_review.compared)+' 份中選出：'+esc(one(t.plan.ai_review.reason,120))+'</div>':'')+'<div class="muted rvS">'+esc(one(t.result,80))+'</div></span></label><div class="rvF" style="display:none;white-space:pre-wrap;font-size:14px;line-height:1.5;margin-top:6px;border-top:1px solid #1f2937;padding-top:6px">'+esc(t.result||'（沒有內容）')+'</div></div>'}).join('')||'<p class="muted">沒有待審項目。</p>')+'</div>');
  function cs(){return Array.prototype.slice.call(sh.querySelectorAll('.rvC'))}
  function upd(){var n=cs().filter(function(c){return c.checked}).length;$('rvN').textContent='已勾選 '+n+' / '+L.length;$('rvAll').checked=n===L.length&&n>0}
  upd();$('rvAll').onchange=function(){var v=this.checked;cs().forEach(function(c){c.checked=v});upd()};cs().forEach(function(c){c.onchange=upd;c.onclick=function(e){e.stopPropagation()}});
  sh.querySelectorAll('#rvL .card').forEach(function(cd){cd.querySelector('span').onclick=function(e){e.preventDefault();var f=cd.querySelector('.rvF');f.style.display=f.style.display==='none'?'block':'none'}});
  async function bulk(dec){var ids=cs().filter(function(c){return c.checked}).map(function(c){return c.dataset.id});if(!ids.length){$('rvE').textContent='沒有勾選任何項目';return}
   if(!confirm((dec==='approve'?'核准':'退回')+'已勾選的 '+ids.length+' 筆？'+(dec==='reject'?'\n（小說大綱／章節退回會排入重寫任務）':'')))return;
   $('rvOk').disabled=$('rvNo').disabled=true;var ok=0,bad=0;
   for(var i=0;i<ids.length;i++){$('rvE').textContent='處理中 '+(i+1)+'/'+ids.length+'…';try{await api('floor','review',{task_id:ids[i],decision:dec});ok++;var c=sh.querySelector('.rvC[data-id="'+ids[i]+'"]');if(c)c.closest('.card').remove()}catch(e){bad++}}
   $('rvE').textContent='完成：'+ok+' 筆成功'+(bad?('，'+bad+' 筆失敗'):'');$('rvOk').disabled=$('rvNo').disabled=false;L=L.filter(function(t){return!!sh.querySelector('.rvC[data-id="'+t.id+'"]')});upd();try{load()}catch(_){}}
  $('rvAI').onclick=async function(e){e.preventDefault();open('<h3>🤖 AI 初審紀錄</h3><p class="muted">載入中…</p>');try{var r=await api('degree','peer_reviews',{limit:50});open('<h3>🤖 AI 初審紀錄（唯讀）</h3><p><a href="#" id="rvBack" style="color:#a5b4fc">← 回作品審核</a></p>'+((r.rows||[]).map(function(x){return'<div class="card"><b>'+esc(x.verdict)+'</b> <span class="muted">審查者 '+esc(x.reviewer_id)+' · '+esc(tp(x.created_at))+'</span><div style="white-space:pre-wrap">'+esc(x.notes)+'</div></div>'}).join('')||'<p class="muted">還沒有 AI 初審紀錄。</p>'));$('rvBack').onclick=function(e){e.preventDefault();showReviews()}}catch(er){sh.innerHTML+='<p class="muted">'+esc(er.message)+'</p>'}};
  $('rvOk').onclick=function(){bulk('approve')};$('rvNo').onclick=function(){bulk('reject')}};
 try{$('cRev').onclick=showReviews}catch(_){}})();
